async fn restore_session(
    store: &Store,
    session_id: &str,
    target: &str,
    out_dir: &Path,
) -> anyhow::Result<(usize, usize)> {
    let factory = adapter::by_name(target).with_context(|| {
        format!(
            "unknown adapter {target}; known: {}",
            adapter::known_names().join(", ")
        )
    })?;
    let Some(parent) = store.get_session(session_id).await? else {
        bail!("export: session not found: {session_id}");
    };
    let children = store.child_sessions(session_id).await?;
    let mut sessions = vec![parent];
    for child in children {
        let grandchildren = store.child_sessions(&child.id).await?;
        if !grandchildren.is_empty() {
            bail!(
                "lineage-complete-restore supports one subagent level; session {} has child sessions",
                child.id
            );
        }
        let child_id = child.id;
        let stored = store
            .get_session(&child_id)
            .await?
            .with_context(|| format!("export: child session disappeared: {child_id}"))?;
        sessions.push(stored);
    }

    let mut file_count = 0usize;
    for session in &sessions {
        // `source_agent` is `brand` or `brand/sub`; the brand prefix picks fidelity.
        let source_agent = &session.session.source_agent;
        let brand = source_agent.split('/').next().unwrap_or(source_agent);
        let fidelity = if brand == factory.name() {
            adapter::RestoreFidelity::Native
        } else {
            adapter::RestoreFidelity::Foreign
        };
        for file in factory.serialize(session, fidelity)? {
            let path = out_dir.join(&file.relative_path);
            if let Some(parent) = path.parent() {
                tokio::fs::create_dir_all(parent)
                    .await
                    .with_context(|| format!("failed to create {}", parent.display()))?;
            }
            tokio::fs::write(&path, file.bytes)
                .await
                .with_context(|| format!("failed to write {}", path.display()))?;
            file_count += 1;
        }
    }

